function perfectpixel_count_failed_payment_status( $order_id, $order = null ) {
	perfectpixel_count_failed_payment( null, $order ? $order : wc_get_order( $order_id ) );
}

function perfectpixel_count_failed_payment( $error, $order ) {
	if ( ! $order instanceof WC_Order || $order->has_status( 'cancelled' ) || $order->is_paid() ) {
		return;
	}
	$count = (int) $order->get_meta( '_perfectpixel_failed_payments' ) + 1;
	$order->update_meta_data( '_perfectpixel_failed_payments', $count );
	if ( $count >= max( 1, (int) '{{failed_payments_limit}}' ) ) {
		$order->update_status( 'cancelled', sprintf( 'Ακυρώθηκε αυτόματα μετά από %d αποτυχημένες προσπάθειες πληρωμής.', $count ) );
	} else {
		$order->save();
	}
}
